clearScene();setBig(null);
setEq("$$\\hat g=\\textstyle\\sum_t\\nabla_\\theta\\log\\pi_\\theta(a_t|s_t)\\,G_t$$","top");
note("若 G_t 全是大正数",640,300,"r lg");
note("每个动作都被加强",640,360,"r lg");
setCap("回报全为正时，<b>所有</b>动作的概率都被推高 —— 区别只在推多少。");

clearScene();setEq(null);
setBig("减掉一个数就不是原梯度了","凭什么可以随便减");
setCap("这个顾虑很自然 —— 而答案是：<b>只要 b 不依赖动作，期望一点不变</b>。");

clearScene();setBig(null);
setEq("$$\\mathbb{E}_{a\\sim\\pi}\\big[\\nabla\\log\\pi_\\theta(a|s)\\,b(s)\\big]=b(s)\\,\\nabla\\textstyle\\sum_a\\pi_\\theta(a|s)=b(s)\\,\\nabla 1=0$$","top");
note("b(s) 是常数，提出去",640,320,"g lg");
setCap("证明的终点还是那一条：<b>∇1 = 0</b>。");

clearScene();setBig(null);
setEq("$$\\hat g=\\textstyle\\sum_t\\nabla_\\theta\\log\\pi_\\theta(a_t|s_t)\\big(G_t-b(s_t)\\big)$$","top");
note("只保留「比基准好多少」",640,320,"g lg");
setCap("于是可以放心地减：估计量变成 <b>(回报 − 基准)</b>，而期望不变。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"b 只依赖状态",sub:"期望不变 · 可以减",state:"on"},
  {label:"b 依赖动作",sub:"提不出求和号 · 改变梯度",state:"dead"},
  {label:"同一条引理",sub:"与 L8 因果性共用",state:"on"}]});
note("前提就这一条",640,420,"y");
setCap("<b>指名反驳</b>：能减不是因为它小，是因为 <b>b 不依赖动作</b>。");

clearScene();setBig(null);setEq(null);
note("任何 b(s) 都不改期望",640,280,"g lg");
note("那 b 取什么都一样吗",640,350,"y lg");
setCap("上一集证明了<b>任何</b>基线都保持无偏。<b>那还有什么可选的？</b>");

clearScene();setEq(null);
setBig("既然无偏，随便取","反正证明说了任何 b 都行");
setCap("「无偏」是<b>无条件</b>的，「降方差」<b>不是</b> —— 坏基线会把方差加大。");

clearScene();setBig(null);
setEq("$$\\mathrm{Var}=\\mathbb{E}\\big[(R-b)^2\\big]-\\big(\\mathbb{E}[\\cdot]\\big)^2$$","top");
note("关于 b 是二次函数",640,300,"y lg");
note("二次 ⟹ U 形，有唯一最低点",640,360,"g lg");
setCap("方差是 b 的<b>二次函数</b> —— 所以它是一条 U 形曲线，两边都会翘起来。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3,4],step:520,vals:[10201,2601,0,2401,22201],
  x:300,y:430,w:680,h:170,max:24000,
  label:function(i){return ["b=0","b=50","b=101","b=150","b=250"][i];},
  cls:function(i){return i===2?"g":(i===4?"r":"v");},
  fmt:function(v){return String(v);}});
note("梯度期望恒为 −1",640,466,"y");
setCap("实测 U 形：最优基线把方差压到 <b>0</b>，而 b=250 反弹到 <b>22201</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"无偏",sub:"任何 b 都成立",state:"on"},
  {label:"降方差",sub:"只有好 b 成立",state:"dead"},
  {label:"取 b ≈ V(s)",sub:"状态的期望回报",state:"on"}]});
note("两句话必须分开说",640,420,"y");
setCap("<b>指名反驳</b>：无偏无条件，降方差有条件。<b>b 取远了会更糟。</b>");

clearScene();setBig(null);setEq(null);
note("score · 因果性 · 基线",640,280,"b lg");
note("零件齐了",640,350,"g lg");
setCap("L8 到这里的零件已经够了。<b>装配成一个能跑的循环。</b>");

clearScene();setEq(null);
setBig("这是一个新算法","又要单独记一套流程");
setCap("它是<b>模板</b>不是算法 —— 后面所有策略梯度方法都在往这五步里换零件。");

clearScene();setBig(null);setEq(null);
note("① 跑 m 条轨迹",360,250,"b lg","start");
note("② 算 reward-to-go",360,310,"b lg","start");
note("③ 算优势 G − b",360,370,"g lg","start");
setCap("前三步：<b>采样 → 算回报 → 减基线</b>。");

clearScene();setBig(null);setEq(null);
note("④ 最小二乘重拟合 b",360,270,"y lg","start");
note("⑤ 沿 Σ ∇log π · Â 走一步",360,350,"g lg","start");
note("然后回到 ①",360,420,"sm lg","start");
setCap("后两步：<b>重新拟合基线</b>，<b>走一步梯度</b>，然后回到采样。");

